/* validate function form fields */ 
function validate(field,error_msg){ 
       $("#"+field).focus();
       $("#"+field).css({"border":"1px red solid","background":"#ffe6e5"});
       $("#error").show();
       $("#msg").html(error_msg);
 }


/* validating file */
function fileutils(uploadFile, Upgraded){
      var f = document.getElementById(uploadFile).files[0]; 
      var res_size = checkFileSize(f, Upgraded);
      var res_ext = checkExtension(f);
      if(res_size != "success" && res_ext != "success" ) {
      	 var res = res_size + res_ext;
       return validate(uploadFile,res);
      } else if(res_size != "success") {
		    $('#paymentModal').modal('show'); 
			  return validate(uploadFile,res_size); 
      } else if(res_ext != "success") { 
       return validate(uploadFile,res_ext);
      } else {
       $("#error").hide();
       $("#"+uploadFile).css({"border":"1px solid #ccc","background":"#f9f9f9","box-shadow":"inset 0 1px 1px rgba(0,0,0,.075)","transition":"border-color ease-in-out .15s,box-shadow ease-in-out .15s"});
        return "success"; 
      } 
}

/* check file zise */
function checkFileSize(file, Upgraded){
  if(Upgraded == "Y"){
    return "success";
  }
  var maxSize = 5242880; //5MB
  var fileSize = file.size;
  if(fileSize > maxSize) {
   return "File size must be less than 5MB <br> ";
  } else { return "success"; }
}
/* check extension */
function checkExtension(file){
    var fileName = file.name;
    var ext = fileName.substring(fileName.lastIndexOf('.') + 1).toLowerCase();; 
    if(ext == 'jpeg' || ext == 'jpg' || ext == 'png' || ext == 'pdf' || ext == 'bmp' || ext == 'doc' || ext == 'docx' || ext == 'xls' || ext == 'xlsx' || ext == 'ppt' || ext == 'pptx' || ext == 'pub' || ext == 'xps' || ext == 'oxps' || ext == 'odg' || ext == 'odp' || ext == 'odt' || ext == 'txt') {
   return "success";
    } else { return "Selected file type <b>."+ ext+"</b> is not valid"; }

}






