/* Validating emails */


function checkemail(emaillist){
  var emails = emaillist.split(',');
     var valid;
        for (var n = 0; n < emails.length; n++) {
         var email = emails[n].trim();
         var emailReg = /^([\w-\.]+@([\w-]+\.)+[\w-]{2,4})?$/;
         if( !emailReg.test(email) ) {
           valid = "failed"; break;
         } else { valid = "success";  }
        }
 return valid;
}

